import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.D7EuCHIT.js";const _=JSON.parse('{"title":"安全与信任边界","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/security.md","filePath":"plugins/security.md","lastUpdated":1791900767000}'),i={name:"plugins/security.md"};function o(s,t,n,l,h,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="安全与信任边界" tabindex="-1">安全与信任边界 <a class="header-anchor" href="#安全与信任边界" aria-label="Permalink to &quot;安全与信任边界&quot;">​</a></h1><p>原生 <code>.so</code> 在应用进程内运行，可调用系统能力、读应用可读的数据，也可能崩溃整个播放器。目录签名与包摘要保证来源和字节完整，不提供权限沙箱或恶意代码审计。</p><h2 id="三种校验" tabindex="-1">三种校验 <a class="header-anchor" href="#三种校验" aria-label="Permalink to &quot;三种校验&quot;">​</a></h2><table tabindex="0"><thead><tr><th>校验</th><th>保护什么</th></tr></thead><tbody><tr><td>APK 永久签名</td><td>Android 应用升级身份</td></tr><tr><td>插件目录 ECDSA 签名</td><td>可信发布者提供的索引内容</td></tr><tr><td>包 SHA-256 + ZIP/ELF 检查</td><td>下载字节、导入路径、平台与 ABI</td></tr></tbody></table><p>目录使用 P-256、SHA256withECDSA；index.sig 为 DER 签名原始字节，公钥是 Base64 SPKI DER。签名对象是 index.json 的实际字节，不是 JSON 解析后的等价对象。格式化索引后必须重签。</p><p>缓存也重新验签。HTTPS、有界重定向/读入和超时保护网络过程。签名失败保留已验证旧列表，不使用未验证新包。信任组的镜像共用一个公钥。</p><h2 id="密钥" tabindex="-1">密钥 <a class="header-anchor" href="#密钥" aria-label="Permalink to &quot;密钥&quot;">​</a></h2><p>APK JKS 与目录签名私钥用途不同。私钥只在维护者本机私有路径，不提交、不嵌入 APK、不写进文档或 CI 日志。发布者保留备份和密钥轮换计划；更换公钥意味着变更用户信任配置，不能仅在镜像换签名后期待旧客户端接受。</p><h2 id="安装与更新" tabindex="-1">安装与更新 <a class="header-anchor" href="#安装与更新" aria-label="Permalink to &quot;安装与更新&quot;">​</a></h2><p>本地同 ID 导入拒绝覆盖；市场更新先在私有 staging 完整校验，原子替换并保留失败恢复路径。卸载不删用户配置，加载器等线程安全退出才释放代码。</p><p>许可证、作者声明与签名来源各自独立：有合法许可证不意味着用户应该信任代码，有签名也不证明元数据里的许可证正确。</p>',11)])])}const u=a(i,[["render",o]]);export{_ as __pageData,u as default};
